#!/usr/bin/env python3
"""Installateur du bouton « Migration vers Render (sauvegarde complète) »
pour le site SAWALI hébergé sur Emergent.

Ce que fait ce script (et RIEN d'autre) :
  1. dépose 3 fichiers (leur contenu est embarqué ci-dessous, vérifié par SHA-256) :
       backend/routes/migration_render.py
       backend/outils/dechiffrer_secrets_migration.py
       frontend/src/pages/admin/sections/MigrationRenderSection.jsx
  2. ajoute 2 lignes dans backend/server.py (enregistrement des routes /api/admin/migration)
  3. ajoute 1 import + 1 bloc dans frontend/src/pages/admin/AdminSettings.jsx
     (section affichée dans AdminSettings > Diagnostics & Logs)
Il peut être relancé sans risque (il ne réinsère pas ce qui existe déjà) ;
relancé avec une version plus récente, il met simplement les 3 fichiers à jour.
v2 : signe de vie, détection des sauvegardes interrompues, reprise, arrêt,
     délais maximum réseau, jauges collection en cours + progression totale.
v3 : coffre chiffré des identifiants Atlas / R2 (restitués avec un mot de passe).

Usage :  python3 installer_migration.py [dossier_du_projet]   (défaut : /app)
"""
import base64
import hashlib
import sys
from pathlib import Path

RACINE = Path(sys.argv[1] if len(sys.argv) > 1 else "/app")

# (chemin relatif, SHA-256 attendu, contenu en base64)
FICHIERS = [
    ("backend/routes/migration_render.py", "aa0d39247747f57a1da27ae8227bc7d6912c662a7f82f28eddf743b7ae55f0c8",
     ""),
    ("backend/outils/dechiffrer_secrets_migration.py", "31163d9721b42730a4bf753093fc4f7d732ac5c55c1ea79e69bd84ddde6c47fe",
     ""),
    ("frontend/src/pages/admin/sections/MigrationRenderSection.jsx", "cc20bf935f0329f25f74805fdcc2dd2165e06f6a58c46a893f23c3ebd379ef0e",
     ""),
]

MARQUE = "migration_render"


def deposer_fichiers():
    for relatif, sha, b64 in FICHIERS:
        donnees = base64.b64decode(b64)
        if hashlib.sha256(donnees).hexdigest() != sha:
            sys.exit(f"ERREUR : contenu altéré pour {relatif}")
        chemin = RACINE / relatif
        chemin.parent.mkdir(parents=True, exist_ok=True)
        chemin.write_bytes(donnees)
        print(f"  ✓ fichier déposé : {relatif}")


def modifier_server():
    chemin = RACINE / "backend/server.py"
    texte = chemin.read_text(encoding="utf-8")
    if MARQUE in texte:
        print("  = server.py déjà à jour")
        return
    ancre = "app.include_router(api)"
    pos = texte.rfind("\n" + ancre)
    if pos < 0:
        sys.exit("ERREUR : ligne « app.include_router(api) » introuvable dans server.py")
    ajout = ("\n# Migration vers Render : sauvegarde complète (base -> MongoDB Atlas, fichiers/archives/secrets -> R2)"
             "\nfrom routes.migration_render import router as _migration_render_router  # noqa: E402"
             "\napi.include_router(_migration_render_router)\n")
    chemin.write_text(texte[:pos] + ajout + texte[pos:], encoding="utf-8")
    print("  ✓ server.py : routes /api/admin/migration enregistrées")


def modifier_admin_settings():
    chemin = RACINE / "frontend/src/pages/admin/AdminSettings.jsx"
    texte = chemin.read_text(encoding="utf-8")
    if "MigrationRenderSection" in texte:
        print("  = AdminSettings.jsx déjà à jour")
        return
    # 1) import : après le dernier import du fichier
    lignes = texte.split("\n")
    dernier_import = max(i for i, l in enumerate(lignes) if l.startswith("import "))
    lignes.insert(dernier_import + 1, 'import MigrationRenderSection from "@/pages/admin/sections/MigrationRenderSection";')
    texte = "\n".join(lignes)
    # 2) section : juste avant le bloc « Stockage de fichiers », sinon avant les instantanés de base
    bloc = ('      {/* Migration vers Render : sauvegarde complète vers MongoDB Atlas + Cloudflare R2 */}\n'
            '      <Filterable title="Migration vers Render (sauvegarde complète)" anchorId="s-migration-render" category="diagnostics">\n'
            '        <MigrationRenderSection />\n'
            '      </Filterable>\n')
    for ancre in ('      <Filterable title="Stockage de fichiers (Object Storage)"', "      <DbSnapshotsSection"):
        pos = texte.find(ancre)
        if pos >= 0:
            texte = texte[:pos] + bloc + texte[pos:]
            break
    else:
        sys.exit("ERREUR : emplacement de la section introuvable dans AdminSettings.jsx")
    chemin.write_text(texte, encoding="utf-8")
    print("  ✓ AdminSettings.jsx : section « Migration vers Render » ajoutée (onglet Diagnostics & Logs)")


if __name__ == "__main__":
    if not (RACINE / "backend/server.py").exists():
        sys.exit(f"ERREUR : {RACINE}/backend/server.py introuvable (indiquez le dossier du projet)")
    print(f"Installation dans {RACINE} :")
    deposer_fichiers()
    modifier_server()
    modifier_admin_settings()
    print("Terminé. Redémarrez le serveur (ou redéployez) pour activer le bouton.")
